  trait ComponentSpec {
    predicate Valid()
    function Evaluate(): SMCE_Result
  }

  // Relations between components
  datatype Relation = Adjacent(comp1: ComponentSpec, comp2: ComponentSpec)
                   | Dependent(parent: ComponentSpec, child: ComponentSpec)

  // Cycle detection logic (addressing RFC358 concerns)
  predicate NoCycles(components: set<ComponentSpec>, rels: set<Relation>) {
    // Graph-based cycle detection using Dafny's built-in well-foundedness
    forall c: ComponentSpec | c in components :: 
      !ExistsPath(c, c, rels, components)
  }

  predicate ExistsPath(start: ComponentSpec, end: ComponentSpec, 
                       rels: set<Relation>, visited: set<ComponentSpec>) 
    decreases |visited|
  {
    if start == end then true
    else if start in visited then false
    else exists r: Relation | r in rels && r.IsSource(start) :: 
      ExistsPath(r.GetTarget(), end, rels, visited + {start})
  }
}
