// ==================== SMCE Specification Library ====================
module SMCE_Spec {
  // Core types
  type SymbolID
  type Judgment
  type ComponentID

  datatype SMCE_Result = Result(
    componentId: ComponentID,
    values: seq<bool>,
    metadata: map<string, string>
  )

  trait ComponentSpec {
    predicate Valid()
    function GetId(): ComponentID
    function Evaluate(): SMCE_Result
      ensures result.Valid()
  }

  datatype Relation = 
    | Adjacent(source: ComponentID, target: ComponentID)
    | Dependent(parent: ComponentID, child: ComponentID)

  // Cycle detection with proper termination metrics
  predicate HasCycle(components: set<ComponentID>, 
                     relations: set<Relation>) 
  {
    exists start: ComponentID | start in components :: 
      ExistsPath(start, start, relations, components, {})
  }

  predicate ExistsPath(start: ComponentID, end: ComponentID,
                       relations: set<Relation>,
                       allComponents: set<ComponentID>,
                       visited: set<ComponentID>)
    decreases |allComponents| - |visited|
  {
    start in allComponents && end in allComponents &&
    if start == end then true
    else if start in visited then false
    else exists r: Relation | r in relations && r.source == start :: 
      ExistsPath(r.target, end, relations, allComponents, visited + {start})
  }

  predicate NoCycles(components: set<ComponentID>, 
                     relations: set<Relation>) 
  {
    !HasCycle(components, relations)
  }
}

// ==================== Main Implementation ====================
module Main {
  import opened SMCE_Spec

  class DictResult {
    var dict: map<int, SMCE_Result>
    var judgments: map<int, Judgment>
    var components: set<ComponentID>
    var relations: set<Relation>

    predicate Valid() 
      reads this
    {
      // Dictionary consistency
      && |dict| == |judgments|
      && (forall i :: i in dict.Keys ==> i in judgments.Keys)
      // All results reference valid components
      && (forall i :: i in dict.Keys ==> dict[i].componentId in components)
      // No cycles in component graph
      && NoCycles(components, relations)
    }

    method Init(symbolTable: map<SymbolID, seq<bool>>) 
      returns (result: DictResult)
      ensures result.Valid()
    {
      result := new DictResult();
      result.dict := map[];
      result.judgments := map[];
      result.components := {};
      result.relations := {};

      var index := 0;
      for symbolId in symbolTable.Keys
        invariant result.Valid()
        invariant index == |result.dict|
      {
        var componentId :| componentId is ComponentID && componentId !in result.components;
        var smceResult := Result(componentId, symbolTable[symbolId], map[]);
        var judgment := ComputeJudgment(smceResult);

        result.dict := result.dict[index := smceResult];
        result.judgments := result.judgments[index := judgment];
        result.components := result.components + {componentId};
        index := index + 1;
      }
    }

