      requires NoCycles(components + {result.componentId}, 
                       relations + newRelations)
      ensures d'.Valid()
    {
      d' := new DictResult();
      d'.dict := dict[id := result];
      d'.judgments := judgments[id := judgment];
      d'.components := components + {result.componentId};
      d'.relations := relations + newRelations;
    }

    function GetResultForComponent(cid: ComponentID): SMCE_Result
      requires cid in components
      reads this
    {
      // Find the result for this component
      var i :| i in dict.Keys && dict[i].componentId == cid;
      dict[i]
    }

    function ComputeJudgment(result: SMCE_Result): Judgment
      requires result.Valid()
    {
      // Judgment computation logic
      if |result.values| > 0 && result.values[0] then
        Judgment.Pass
      else
        Judgment.Fail
    }
  }

  // Example usage with model verification
  datatype ModelType = 
    | MyModel(data: seq<int>)
    | FullModel(data: map<string, int>)

  method CalculateModelOutput(model: ModelType) 
    returns (output: seq<int>)
    ensures |output| > 0
  {
    match model {
      case MyModel(data) => 
        output := data;
      case FullModel(data) =>
        var result := [];
        for key in data.Keys {
          result := result + [data[key]];
        }
        output := result;
    }
  }

  method Main() {
    // Example initialization
    var symbolTable := map[
      "sym1" := [true, false, true],
      "sym2" := [false, true, false]
    ];

    var dictResult := new DictResult().Init(symbolTable);
    print "Dictionary initialized with ", |dictResult.dict|, " entries\n";

    // Verify the dictionary is valid
    assert dictResult.Valid();
  }
}
