class LinearRegression {
  var m: real  // slope
  var b: real  // intercept

  constructor() {
    m := 0.0;
    b := 0.0;
  }

  // Train using gradient descent
  method Train(data: seq<TrainingExample>, learningRate: real, iterations: int)
    modifies this
  {
    var n := |data|;

    for i := 0 to iterations - 1 {
